import React, { useState, useEffect } from "react";
import { useAuth } from "../context/AuthContext";
import api from "../utils/api";
import toast from "react-hot-toast";

const typeColor = { holiday:"#10b981", event:"#3b82f6", exam:"#ef4444", deadline:"#f59e0b", other:"#8b5cf6" };
const inp = { width:"100%", padding:"9px 12px", background:"var(--bg3)", border:"1px solid var(--border)", borderRadius:8, color:"var(--text)", fontSize:13, outline:"none" };

export default function Events() {
  const { user } = useAuth();
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ title:"", description:"", date:"", endDate:"", type:"event", venue:"" });
  const canEdit = user?.role === "admin" || user?.role === "teacher";

  useEffect(()=>{
    api.get("/events").then(r=>setEvents(r.data)).catch(()=>{}).finally(()=>setLoading(false));
  }, []);

  const submit = async () => {
    if (!form.title || !form.date) return toast.error("Title and date required");
    const { data } = await api.post("/events", form).catch(err=>{ toast.error(err.response?.data?.message||"Error"); return {}; });
    if (data) { setEvents(p=>[...p,data].sort((a,b)=>new Date(a.date)-new Date(b.date))); setShowForm(false); setForm({ title:"", description:"", date:"", endDate:"", type:"event", venue:"" }); toast.success("Event created!"); }
  };

  const del = async (id) => {
    await api.delete(`/events/${id}`);
    setEvents(p=>p.filter(e=>e._id!==id));
    toast.success("Deleted");
  };

  const upcoming = events.filter(e=>new Date(e.date)>=new Date());
  const past = events.filter(e=>new Date(e.date)<new Date());

  const EventCard = ({ ev }) => (
    <div style={{ background:"var(--card)", border:"1px solid var(--border)", borderRadius:12, padding:16, position:"relative", borderLeft:`3px solid ${typeColor[ev.type]||"#8b5cf6"}` }}>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:8 }}>
        <span style={{ fontSize:10, fontWeight:600, padding:"2px 8px", borderRadius:10, background:typeColor[ev.type]+"22", color:typeColor[ev.type], textTransform:"uppercase" }}>{ev.type}</span>
        {canEdit && <button onClick={()=>del(ev._id)} style={{ background:"none", border:"none", color:"var(--text3)", cursor:"pointer", fontSize:16 }}>×</button>}
      </div>
      <h3 style={{ fontSize:14, fontWeight:600, marginBottom:4 }}>{ev.title}</h3>
      {ev.description && <p style={{ fontSize:12, color:"var(--text2)", marginBottom:6, lineHeight:1.5 }}>{ev.description}</p>}
      <div style={{ fontSize:11, color:"var(--text3)", display:"flex", gap:10, flexWrap:"wrap" }}>
        <span>📅 {new Date(ev.date).toLocaleDateString("en-IN",{ day:"numeric", month:"short", year:"numeric" })}</span>
        {ev.venue && <span>📍 {ev.venue}</span>}
        {ev.createdBy && <span>by {ev.createdBy.name}</span>}
      </div>
    </div>
  );

  return (
    <div style={{ padding:24, maxWidth:900, margin:"0 auto" }} className="fade-in">
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:20, flexWrap:"wrap", gap:12 }}>
        <div>
          <h1 style={{ fontSize:20, fontWeight:700 }}>Events & Holidays</h1>
          <p style={{ color:"var(--text2)", fontSize:13, marginTop:3 }}>Academic calendar</p>
        </div>
        {canEdit && (
          <button onClick={()=>setShowForm(true)} style={{ padding:"9px 16px", borderRadius:8, background:"linear-gradient(135deg,#3b82f6,#6366f1)", border:"none", color:"#fff", fontWeight:600, fontSize:13, cursor:"pointer" }}>
            + Add Event
          </button>
        )}
      </div>

      {/* Add Modal */}
      {showForm && (
        <div style={{ position:"fixed", inset:0, background:"rgba(0,0,0,0.65)", display:"flex", alignItems:"center", justifyContent:"center", zIndex:50 }}>
          <div style={{ background:"var(--card)", border:"1px solid var(--border)", borderRadius:16, padding:24, width:420, maxWidth:"90vw" }}>
            <h2 style={{ fontWeight:600, fontSize:16, marginBottom:16 }}>Add Event / Holiday</h2>
            <div style={{ display:"flex", flexDirection:"column", gap:11 }}>
              {[["Title","title","text"],["Description","description","text"],["Venue","venue","text"]].map(([lbl,key,type])=>(
                <div key={key}>
                  <label style={{ fontSize:11, color:"var(--text2)", display:"block", marginBottom:4 }}>{lbl}</label>
                  <input style={inp} type={type} value={form[key]} onChange={e=>setForm(p=>({...p,[key]:e.target.value}))} />
                </div>
              ))}
              <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10 }}>
                <div>
                  <label style={{ fontSize:11, color:"var(--text2)", display:"block", marginBottom:4 }}>Type</label>
                  <select style={inp} value={form.type} onChange={e=>setForm(p=>({...p,type:e.target.value}))}>
                    {["holiday","event","exam","deadline","other"].map(t=><option key={t}>{t}</option>)}
                  </select>
                </div>
                <div>
                  <label style={{ fontSize:11, color:"var(--text2)", display:"block", marginBottom:4 }}>Date</label>
                  <input style={inp} type="date" value={form.date} onChange={e=>setForm(p=>({...p,date:e.target.value}))} />
                </div>
              </div>
            </div>
            <div style={{ display:"flex", gap:10, marginTop:18 }}>
              <button onClick={()=>setShowForm(false)} style={{ flex:1, padding:"10px", borderRadius:8, background:"var(--bg3)", border:"1px solid var(--border)", color:"var(--text)", cursor:"pointer" }}>Cancel</button>
              <button onClick={submit} style={{ flex:1, padding:"10px", borderRadius:8, background:"linear-gradient(135deg,#3b82f6,#6366f1)", border:"none", color:"#fff", fontWeight:600, cursor:"pointer" }}>Save</button>
            </div>
          </div>
        </div>
      )}

      {loading ? <p style={{ color:"var(--text3)" }}>Loading...</p> : (
        <>
          <h2 style={{ fontSize:14, fontWeight:600, color:"var(--text2)", marginBottom:12 }}>Upcoming ({upcoming.length})</h2>
          {upcoming.length===0 ? <p style={{ color:"var(--text3)", fontSize:13, marginBottom:24 }}>No upcoming events</p> : (
            <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fill,minmax(280px,1fr))", gap:12, marginBottom:28 }}>
              {upcoming.map(ev=><EventCard key={ev._id} ev={ev} />)}
            </div>
          )}
          {past.length>0 && (
            <>
              <h2 style={{ fontSize:14, fontWeight:600, color:"var(--text3)", marginBottom:12 }}>Past Events</h2>
              <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fill,minmax(280px,1fr))", gap:12, opacity:0.6 }}>
                {past.map(ev=><EventCard key={ev._id} ev={ev} />)}
              </div>
            </>
          )}
        </>
      )}
    </div>
  );
}
